// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(address caller) internal {
        caller = c.smartfix_owner();
        caller = msg.sender;
        caller = address(this);
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == false);
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable { }
}
